package com.gomgomapps.math.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class NamibiaSeniorOrdinalTest {
 private static final String NA="na-nied-primary-2024-v1";
 private void verify(Question q){double[] v=q.diagram.values;int before=(int)(v[2]==0?v[1]:v[0]-v[1]-1),answer=before+1;q.answers=new String[]{"poison"};Checker c=new Checker();assertTrue(c.check(q,List.of(),List.of(""+answer)).correct());assertFalse(c.check(q,List.of(),List.of(""+(answer+1))).correct());PrimaryOrdering.attach(q);HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertEquals(2,h.size());assertTrue(h.step(0).accepts(""+before));assertTrue(h.step(1).accepts(""+answer));}
 @Test public void freshGradeSixBothDirectionsAndPublicGeometry(){Generator g=new Generator(new Random(257));List<String> recent=new ArrayList<>();Set<Integer> directions=new HashSet<>();var limits=GlobalCurriculum.limits(NA,"objectOrdinal",6);for(int i=0;i<150;i++){Question q=g.next("objectOrdinal",recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertTrue(q.diagram.values[0]>=1&&q.diagram.values[0]<=30);directions.add((int)q.diagram.values[2]);verify(q);}assertEquals(Set.of(0,1),directions);}
 @Test public void completeThirtyObjectGeometryAndInvalidMarks(){for(int i=0;i<PrimaryOrdering.conditionCount("objectOrdinal",30);i++)verify(PrimaryOrdering.make("objectOrdinal",PrimaryOrdering.conditionAt("objectOrdinal",30,i)));Question q=PrimaryOrdering.make("objectOrdinal",new int[]{30,29,0});assertTrue(GlobalCurriculum.limits(NA,"objectOrdinal",6).allows(q));assertFalse(GlobalCurriculum.limits(NA,"objectOrdinal",1).allows(q));q.diagram.values[1]=30;assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("31")).status);}
}
